#!/usr/bin/env bash # ====================================================== # VLESS+WS 一键部署（容器/PaaS 专用版） # 用法：bash install.sh # ====================================================== set -e # ---------- 固定参数（可改） ---------- WS_PATH="${WS_PATH:-/vless}" # WebSocket 路径，可用环境变量覆盖 # ------------------------------------ # 颜色输出 if [ -t 1 ]; then  RED='\033[0;31m'; GREEN='\033[0;32m'; YELLOW='\033[0;33m'; NC='\033[0m' else  RED=''; GREEN=''; YELLOW=''; NC='' fi echo -e "${GREEN}>>> 容器环境部署 VLESS+WS ...${NC}" # 1. 安装依赖 install_deps() {  echo -e "${GREEN}>>> 安装依赖...${NC}"  if command -v apt &> /dev/null; then  apt update -y && apt install -y curl unzip wget openssl uuid-runtime  elif command -v yum &> /dev/null; then  yum install -y curl unzip wget openssl util-linux  elif command -v apk &> /dev/null; then  apk add --no-cache curl unzip wget openssl util-linux bash  else  echo -e "${YELLOW}警告：未知包管理器，请确保 curl、unzip 已安装${NC}"  fi } # 2. 生成 UUID generate_uuid() {  if command -v uuidgen &> /dev/null; then  uuidgen  elif [ -f /proc/sys/kernel/random/uuid ]; then  cat /proc/sys/kernel/random/uuid  else  echo "$(openssl rand -hex 8)-$(openssl rand -hex 4)-$(openssl rand -hex 4)-$(openssl rand -hex 4)-$(openssl rand -hex 12)"  fi } # 3. 自动获取平台域名 get_platform_domain() {  [ -n "$RAILWAY_PUBLIC_DOMAIN" ] && { echo "$RAILWAY_PUBLIC_DOMAIN"; return; }  [ -n "$HEROKU_APP_NAME" ] && { echo "${HEROKU_APP_NAME}.herokuapp.com"; return; }  [ -n "$PUBLIC_URL" ] && { echo "$PUBLIC_URL" | sed 's|https://||;s|http://||'; return; }  [ -n "$HOSTNAME" ] && echo "$HOSTNAME" | grep -q '\.' && { echo "$HOSTNAME"; return; }  echo "" } # ==========主流程 ========== main() {  install_deps  UUID=$(generate_uuid)  echo -e "${GREEN}>>> UUID: ${YELLOW}$UUID${NC}"  # 获取端口（优先使用平台 $PORT 环境变量）  LISTEN_PORT="${PORT:-8080}"  echo -e "${GREEN}>>> 端口: ${YELLOW}$LISTEN_PORT${NC}"  # 下载 Xray  mkdir -p /usr/local/bin /etc/xray  echo -e "${GREEN}>>> 下载 Xray 核心...${NC}"  ARCH=$(uname -m)  case $ARCH in  x86_64) XARCH="64" ;;  aarch64) XARCH="arm64-v8a" ;;  armv7l) XARCH="armv7a" ;;  *) XARCH="64" ;;  esac  for i in {1..3}; do  curl -L -o /tmp/xray.zip "https://github.com/XTLS/Xray-core/releases/latest/download/Xray-linux-${XARCH}.zip" && break  echo -e "${YELLOW}下载失败，重试 $i/3...${NC}"; sleep 2  done  unzip -o /tmp/xray.zip -d /tmp/xray  cp /tmp/xray/xray /usr/local/bin/  chmod +x /usr/local/bin/xray  # 生成配置  cat > /etc/xray/config.json <<EOF {  "log":{ "loglevel":"warning" },  "inbounds":[{  "port":$LISTEN_PORT,  "protocol":"vless",  "settings":{  "clients":[{ "id":"$UUID", "flow":"" }],  "decryption":"none"  },  "streamSettings":{  "network":"ws",  "wsSettings":{ "path":"$WS_PATH" }  },  "sniffing":{ "enabled":true, "destOverride":["http","tls"] }  }],  "outbounds":[{ "protocol":"freedom", "tag":"direct" }] } EOF  # 输出节点信息  PLATFORM_DOMAIN=$(get_platform_domain)  echo ""  echo "======================================================"  echo -e "${GREEN}✅ 部署完成！${NC}"  echo ""  if [ -n "$PLATFORM_DOMAIN" ]; then  echo -e "${GREEN}>>> 自动检测到平台域名: ${YELLOW}$PLATFORM_DOMAIN${NC}"  echo ""  echo "【节点链接（复制到 V2RayN 导入）】"  echo -e "${GREEN}vless://$UUID@$PLATFORM_DOMAIN:443?encryption=none&security=tls&sni=$PLATFORM_DOMAIN&fp=chrome&type=ws&host=$PLATFORM_DOMAIN&path=%2Fvless#容器节点${NC}"  echo ""  echo "【V2RayN 手动填写】"  echo "地址: $PLATFORM_DOMAIN"  echo "端口: 443"  echo "用户ID: $UUID"  echo "加密: none"  echo "传输协议: ws"  echo "路径: $WS_PATH"  echo "TLS: 开启"  echo "SNI: $PLATFORM_DOMAIN"  else  echo -e "${YELLOW}【请手动填写平台域名】${NC}"  echo "将下面「你的平台域名」替换为平台给你的公共地址"  echo ""  echo "【节点链接模板】"  echo -e "${GREEN}vless://$UUID@你的平台域名:443?encryption=none&security=tls&sni=你的平台域名&fp=chrome&type=ws&host=你的平台域名&path=%2Fvless#容器节点${NC}"  echo ""  echo "【V2RayN 手动填写】"  echo "地址: 你的平台域名"  echo "端口: 443"  echo "用户ID: $UUID"  echo "加密: none"  echo "传输协议: ws"  echo "路径: $WS_PATH"  echo "TLS: 开启"  echo "SNI: 你的平台域名"  fi  echo ""  echo -e "${YELLOW}内部监听端口: $LISTEN_PORT${NC}"  echo -e "${YELLOW}WS 路径: $WS_PATH${NC}"  echo "======================================================"  echo ""  exec /usr/local/bin/xray run -config /etc/xray/config.json } main
